INSERT INTO plantillas_rutina_textos (plantilla_id, idioma, nombre, descripcion)
VALUES
('52b9a26c-51eb-52d4-b8c7-e8faae2bfdf5'::uuid, 'es', 'Máquinas para empezar · 3 días', 'Todo con máquinas guiadas: fáciles de aprender y seguras si es tu primer gimnasio.'),
('52b9a26c-51eb-52d4-b8c7-e8faae2bfdf5'::uuid, 'en', 'Machines to get started · 3 days', 'All on guided machines: easy to learn and safe if it''s your first gym.'),
('52b9a26c-51eb-52d4-b8c7-e8faae2bfdf5'::uuid, 'fr', 'Machines pour débuter · 3 jours', 'Tout sur machines guidées : faciles à apprendre et sûres si c''est ta première salle.'),
('52b9a26c-51eb-52d4-b8c7-e8faae2bfdf5'::uuid, 'pt', 'Máquinas para começar · 3 dias', 'Tudo em máquinas guiadas: fáceis de aprender e seguras se é o teu primeiro ginásio.'),
('0298a483-63eb-518b-a311-dda975430ca1'::uuid, 'es', 'Calistenia en el parque · 3 días', 'Barras, paralelas y un banco del parque. Gratis y al aire libre.'),
('0298a483-63eb-518b-a311-dda975430ca1'::uuid, 'en', 'Park calisthenics · 3 days', 'Bars, dip bars and a park bench. Free and outdoors.'),
('0298a483-63eb-518b-a311-dda975430ca1'::uuid, 'fr', 'Street workout au parc · 3 jours', 'Barres, barres parallèles et un banc du parc. Gratuit et en plein air.'),
('0298a483-63eb-518b-a311-dda975430ca1'::uuid, 'pt', 'Calistenia no parque · 3 dias', 'Barras, paralelas e um banco do parque. Grátis e ao ar livre.'),
('04810930-a3d8-5ad6-866a-08dbccbdd8ba'::uuid, 'es', 'Exprés 30 min · gimnasio · 3 días', 'Cuatro ejercicios y descansos cortos. Entras, entrenas y vuelves a estudiar.'),
('04810930-a3d8-5ad6-866a-08dbccbdd8ba'::uuid, 'en', 'Express 30 min · gym · 3 days', 'Four exercises and short rests. In, train and back to studying.'),
('04810930-a3d8-5ad6-866a-08dbccbdd8ba'::uuid, 'fr', 'Express 30 min · salle · 3 jours', 'Quatre exercices et des repos courts. Tu entres, tu t''entraînes et tu retournes réviser.'),
('04810930-a3d8-5ad6-866a-08dbccbdd8ba'::uuid, 'pt', 'Expresso 30 min · ginásio · 3 dias', 'Quatro exercícios e descansos curtos. Entras, treinas e voltas a estudar.'),
('2c30695d-e6a1-5f56-9359-2d4fdf65013d'::uuid, 'es', 'En casa · torso y pierna · 4 días', 'Sin material y más exigente: para cuando las rutinas de casa se te quedan cortas.'),
('2c30695d-e6a1-5f56-9359-2d4fdf65013d'::uuid, 'en', 'At home · upper and lower · 4 days', 'No equipment and more demanding: for when home routines feel too easy.'),
('2c30695d-e6a1-5f56-9359-2d4fdf65013d'::uuid, 'fr', 'À la maison · haut et bas · 4 jours', 'Sans matériel et plus exigeant : quand les routines maison deviennent trop faciles.'),
('2c30695d-e6a1-5f56-9359-2d4fdf65013d'::uuid, 'pt', 'Em casa · tronco e pernas · 4 dias', 'Sem material e mais exigente: para quando as rotinas de casa já te sabem a pouco.'),
('cff9fca4-c024-5a2e-be43-b30406360951'::uuid, 'es', 'Empuje, tirón y pierna · 3 días', 'Un día para empujar (pecho, hombro, tríceps), otro para tirar (espalda, bíceps) y otro de pierna.'),
('cff9fca4-c024-5a2e-be43-b30406360951'::uuid, 'en', 'Push, pull and legs · 3 days', 'One day to push (chest, shoulders, triceps), one to pull (back, biceps) and one for legs.'),
('cff9fca4-c024-5a2e-be43-b30406360951'::uuid, 'fr', 'Poussée, tirage et jambes · 3 jours', 'Un jour pour pousser (pecs, épaules, triceps), un pour tirer (dos, biceps) et un pour les jambes.'),
('cff9fca4-c024-5a2e-be43-b30406360951'::uuid, 'pt', 'Empurrar, puxar e pernas · 3 dias', 'Um dia para empurrar (peito, ombros, tríceps), outro para puxar (costas, bíceps) e outro de pernas.'),
('e9860fa2-6288-5be3-bccf-369cad93f427'::uuid, 'es', 'Empuje, tirón y pierna · 6 días', 'El mismo reparto dos veces por semana. Solo si ya entrenas a menudo y duermes bien.'),
('e9860fa2-6288-5be3-bccf-369cad93f427'::uuid, 'en', 'Push, pull and legs · 6 days', 'The same split twice a week. Only if you already train often and sleep well.'),
('e9860fa2-6288-5be3-bccf-369cad93f427'::uuid, 'fr', 'Poussée, tirage et jambes · 6 jours', 'La même répartition deux fois par semaine. Seulement si tu t''entraînes déjà souvent et dors bien.'),
('e9860fa2-6288-5be3-bccf-369cad93f427'::uuid, 'pt', 'Empurrar, puxar e pernas · 6 dias', 'A mesma divisão duas vezes por semana. Só se já treinas com frequência e dormes bem.'),
('1c218d91-dd6c-5c3b-8d39-d1b4dccc6efc'::uuid, 'es', 'Solo mancuernas · 3 días', 'Con un par de mancuernas en tu cuarto trabajas todo el cuerpo.'),
('1c218d91-dd6c-5c3b-8d39-d1b4dccc6efc'::uuid, 'en', 'Dumbbells only · 3 days', 'A pair of dumbbells in your room is enough for your whole body.'),
('1c218d91-dd6c-5c3b-8d39-d1b4dccc6efc'::uuid, 'fr', 'Haltères uniquement · 3 jours', 'Une paire d''haltères dans ta chambre suffit pour tout le corps.'),
('1c218d91-dd6c-5c3b-8d39-d1b4dccc6efc'::uuid, 'pt', 'Só halteres · 3 dias', 'Com um par de halteres no teu quarto trabalhas o corpo todo.'),
('3a953208-d700-5067-b00a-d641602db9af'::uuid, 'es', 'Con gomas elásticas · 3 días', 'Caben en la mochila: para casa, la residencia o cuando viajas.'),
('3a953208-d700-5067-b00a-d641602db9af'::uuid, 'en', 'Resistance bands · 3 days', 'They fit in your backpack: for home, halls or when you travel.'),
('3a953208-d700-5067-b00a-d641602db9af'::uuid, 'fr', 'Avec élastiques · 3 jours', 'Ils tiennent dans le sac : pour la maison, la résidence ou en voyage.'),
('3a953208-d700-5067-b00a-d641602db9af'::uuid, 'pt', 'Com elásticos · 3 dias', 'Cabem na mochila: para casa, a residência ou quando viajas.'),
('4466d33a-3864-5ead-a423-80c51d0e4dc5'::uuid, 'es', 'Una pesa rusa · 3 días', 'Con una sola kettlebell: fuerza y fondo en media hora.'),
('4466d33a-3864-5ead-a423-80c51d0e4dc5'::uuid, 'en', 'One kettlebell · 3 days', 'Just one kettlebell: strength and stamina in half an hour.'),
('4466d33a-3864-5ead-a423-80c51d0e4dc5'::uuid, 'fr', 'Un kettlebell · 3 jours', 'Un seul kettlebell : force et endurance en une demi-heure.'),
('4466d33a-3864-5ead-a423-80c51d0e4dc5'::uuid, 'pt', 'Um kettlebell · 3 dias', 'Só com um kettlebell: força e resistência em meia hora.'),
('5554226f-b200-588a-b786-5bce73d71260'::uuid, 'es', 'De 0 a 5 km', 'Tres salidas a correr por semana y un día corto de fuerza. Empieza alternando andar y correr y termina corriendo 30 minutos seguidos.'),
('5554226f-b200-588a-b786-5bce73d71260'::uuid, 'en', 'From 0 to 5 km', 'Three runs a week and one short strength day. Start by alternating walking and running and finish running 30 minutes non-stop.'),
('5554226f-b200-588a-b786-5bce73d71260'::uuid, 'fr', 'De 0 à 5 km', 'Trois sorties de course par semaine et une courte séance de force. Commence en alternant marche et course et finis par courir 30 minutes d''affilée.'),
('5554226f-b200-588a-b786-5bce73d71260'::uuid, 'pt', 'Dos 0 aos 5 km', 'Três corridas por semana e um dia curto de força. Começa a alternar caminhar e correr e acaba a correr 30 minutos seguidos.'),
('55155890-7cb0-5cbb-814e-a970a297c60c'::uuid, 'es', 'Correr y fuerza · 2 + 2', 'Dos días de gimnasio y dos salidas a correr: una suave y otra con cambios de ritmo.'),
('55155890-7cb0-5cbb-814e-a970a297c60c'::uuid, 'en', 'Running and strength · 2 + 2', 'Two gym days and two runs: one easy and one with pace changes.'),
('55155890-7cb0-5cbb-814e-a970a297c60c'::uuid, 'fr', 'Course et force · 2 + 2', 'Deux jours de salle et deux sorties de course : une tranquille et une avec changements de rythme.'),
('55155890-7cb0-5cbb-814e-a970a297c60c'::uuid, 'pt', 'Corrida e força · 2 + 2', 'Dois dias de ginásio e duas corridas: uma leve e outra com mudanças de ritmo.'),
('b3405b27-aeab-522c-8c9c-febb6fa7080a'::uuid, 'es', 'Espalda sana · 10 min · 5 días', 'Movilidad y abdomen para pasar muchas horas sentado sin que la espalda lo note.'),
('b3405b27-aeab-522c-8c9c-febb6fa7080a'::uuid, 'en', 'Healthy back · 10 min · 5 days', 'Mobility and core work so long hours sitting don''t hurt your back.'),
('b3405b27-aeab-522c-8c9c-febb6fa7080a'::uuid, 'fr', 'Dos en forme · 10 min · 5 jours', 'Mobilité et gainage pour rester assis des heures sans que ton dos le sente.'),
('b3405b27-aeab-522c-8c9c-febb6fa7080a'::uuid, 'pt', 'Costas saudáveis · 10 min · 5 dias', 'Mobilidade e abdómen para passares muitas horas sentado sem que as costas sintam.'),
('b9d8c5bc-708b-5125-9d81-f971a5c567ad'::uuid, 'es', 'Glúteo y pierna · 3 días', 'Tres días centrados en glúteos y piernas, con algo de abdomen.'),
('b9d8c5bc-708b-5125-9d81-f971a5c567ad'::uuid, 'en', 'Glutes and legs · 3 days', 'Three days focused on glutes and legs, with some core work.'),
('b9d8c5bc-708b-5125-9d81-f971a5c567ad'::uuid, 'fr', 'Fessiers et jambes · 3 jours', 'Trois jours centrés sur les fessiers et les jambes, avec un peu de gainage.'),
('b9d8c5bc-708b-5125-9d81-f971a5c567ad'::uuid, 'pt', 'Glúteos e pernas · 3 dias', 'Três dias centrados em glúteos e pernas, com algum abdómen.'),
('6c7184fe-19e7-5536-a4df-b9cd6bfa5255'::uuid, 'es', 'Volver tras los exámenes · 3 días', 'Pocas series para retomar sin agujetas después de exámenes o un parón. Luego pasa a otra rutina.'),
('6c7184fe-19e7-5536-a4df-b9cd6bfa5255'::uuid, 'en', 'Back after exams · 3 days', 'Few sets to get going again without soreness after exams or a break. Then move to another routine.'),
('6c7184fe-19e7-5536-a4df-b9cd6bfa5255'::uuid, 'fr', 'Reprendre après les examens · 3 jours', 'Peu de séries pour reprendre sans courbatures après les examens ou une pause. Ensuite, passe à une autre routine.'),
('6c7184fe-19e7-5536-a4df-b9cd6bfa5255'::uuid, 'pt', 'Voltar depois dos exames · 3 dias', 'Poucas séries para retomar sem dores depois dos exames ou de uma pausa. Depois passa para outra rotina.');

